entries[223814] = { ["name"] = "Mechanischer Holzextraktor", ["text"] = "Wirken in 1.5 sek.\nSteigt in einen mechanischen Holzextraktor, wodurch Ihr sehr schnell fliegen könnt. Die Klauen sind überraschend präzise und können von Kräuterkundigen zum Kräuterpflücken verwendet werden. Das ist ein Flugreittier.\n\"Jepetto hat es vielleicht etwas übertrieben...\"\nErfolg:\nLasst die anderen auch mal spielen\nKategorie:\nSpielzeugkiste" }
