entries[223892] = { ["name"] = "Verbündeten verwandeln", ["text"] = "40 Meter Reichweite\nKanalisiert (Wirken in 10 sek.) 10 sek. Abklingzeit\nLässt nach 10 Sek. 'Dunkles Flüstern' in die Gedanken eines Verbündeten sickern.\n\nDer Einsatz dieser Fähigkeit wird Euch für 15 Sek. als Verbündeten der Legion zu erkennen geben.\n\nEntfernt einen Stapel von 'Schwacher Geist'." }
entries[223894] = { ["name"] = "Hysterie", ["text"] = "50 Meter ReichweiteWirken in 2 sek. 1 min Abklingzeit\nRuft bei einer Gruppe von Zielen eine Hysterie hervor, die sie für 10 Sek. gegen ihre Verbündeten kämpfen lässt.\n\nDer Einsatz dieser Fähigkeit wird Euch für 15 Sek. als Verbündeten der Legion zu erkennen geben.\n\nDie Fähigkeit trifft keine Ziele, die kürzlich bereits hysterisch waren." }
