entries[223898] = { ["name"] = "Der Dunkelheit anheimfallen", ["text"] = "Sofort 5 min Abklingzeit\nWerdet zu einem mächtigen Schreckenslord.\n\nDiese Macht tötet Euch nach 1 Min.\n\nLässt sich nicht einsetzen, wenn der Zaubernde unter 'Schwacher Geist' leidet." }
