entries[224480] = { ["name"] = "Niedere Dämonen beschwören", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.) 3 sek. Abklingzeit\nKanalisiert die Mächte des Nethers und beschwört so 9 Sek. lang alle 3 Sek. einen niederen Dämon." }
