entries[224483] = { ["name"] = "Zerschmettern", ["text"] = "8 Meter Reichweite\nSofort 3 sek. Abklingzeit\nSchlägt mit dem Schild des Zaubernden auf einen Gegner ein, verursacht 5269 körperlichen Schaden, stößt das Ziel zurück und betäubt es für 3 Sek." }
entries[224484] = { ["name"] = "Sternschnuppe", ["text"] = "Wirken in 2.5 sek.\nEine Sternschnuppe stürzt herab und fügt allen Gegnern in der Nähe 38 Arkanschaden zu." }
entries[224487] = { ["name"] = "Stasisfeld", ["text"] = "30 Meter Reichweite\nSofort\nAktiviert ein Stasisfeld auf Zielen innerhalb von 5 Metern um das Zielgebiet und verhindert alle Aktionen, macht sie jedoch auch bis zu 8 Sek. lang unverwundbar." }
entries[224488] = { ["name"] = "Wunden umkehren", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nDreht die Zeit für das Ziel zurück und heilt es im Verlauf von 6 Sek." }
